#!/usr/bin/env node
/**
 * convert-release-sidebar.js
 * Converts a release's sidebars.js snapshot into the versioned sidebar JSON
 * Docusaurus needs, so an archived version keeps the nav it shipped with.
 * Falling back to `autogenerated` builds fine but renders a flat file listing.
 *
 * Usage:
 *   node scripts/convert-release-sidebar.js 1.6.0
 *
 * Exits non-zero if a referenced doc id or autogenerated dirName is missing.
 */

const fs = require('fs');
const os = require('os');
const path = require('path');

const ARCHIVE_DIR = path.join(__dirname, '..');
const REPO_ROOT = path.join(ARCHIVE_DIR, '..');

const version = process.argv[2];
if (!version) {
  console.error('Usage: node scripts/convert-release-sidebar.js X.Y.Z');
  process.exit(1);
}

const srcPath = path.join(REPO_ROOT, 'versioned_sidebars', `version-${version}-sidebars.json`);
const outPath = path.join(ARCHIVE_DIR, 'versioned_sidebars', `version-${version}-sidebars.json`);
const docsDir = path.join(ARCHIVE_DIR, 'versioned_docs', `version-${version}`);

for (const [label, p] of [['release sidebar snapshot', srcPath], ['versioned docs', docsDir]]) {
  if (!fs.existsSync(p)) {
    console.error(`ERROR: ${label} not found: ${p}`);
    process.exit(1);
  }
}

// CommonJS with comments — require() it, and require() needs a .js extension
const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'relsidebar-'));
const tmpJs = path.join(tmpDir, `sidebar-${version}.js`);
let sidebars;
try {
  fs.copyFileSync(srcPath, tmpJs);
  sidebars = require(tmpJs);
} catch (err) {
  console.error(`ERROR: could not evaluate ${srcPath}\n  ${err.message}`);
  process.exit(1);
} finally {
  fs.rmSync(tmpDir, { recursive: true, force: true });
}

if (!sidebars || typeof sidebars !== 'object' || !Object.keys(sidebars).length) {
  console.error('ERROR: snapshot did not export a sidebar object');
  process.exit(1);
}

// only recurse into items, so labels/urls aren't mistaken for doc ids
const docIds = new Set();
const autoDirs = new Set();

function walk(node) {
  if (Array.isArray(node)) return node.forEach(walk);
  if (typeof node === 'string') return docIds.add(node); // shorthand doc id
  if (!node || typeof node !== 'object') return;

  if ((node.type === 'doc' || node.type === 'ref') && typeof node.id === 'string') docIds.add(node.id);
  if (node.link && node.link.type === 'doc' && typeof node.link.id === 'string') docIds.add(node.link.id);
  if (node.type === 'autogenerated' && typeof node.dirName === 'string') autoDirs.add(node.dirName);

  if (Array.isArray(node.items)) node.items.forEach(walk);
}
Object.values(sidebars).forEach(walk);

const missingDocs = [...docIds].filter(
  (id) => !fs.existsSync(path.join(docsDir, `${id}.md`)) && !fs.existsSync(path.join(docsDir, `${id}.mdx`))
);
const missingDirs = [...autoDirs].filter((d) => !fs.existsSync(path.join(docsDir, d)));

console.log(`version-${version}:`);
console.log(`  sidebars           : ${Object.keys(sidebars).join(', ')}`);
console.log(`  doc ids referenced : ${docIds.size}`);
console.log(`  autogenerated dirs : ${autoDirs.size}`);

if (missingDocs.length || missingDirs.length) {
  console.error('\nERROR: refusing to write — the snapshot references content not in this version:');
  missingDocs.forEach((id) => console.error(`  missing doc: ${id}`));
  missingDirs.forEach((d) => console.error(`  missing dir: ${d}`));
  console.error('\nFix the snapshot (or fall back to autogenerated) before building.');
  process.exit(1);
}

fs.writeFileSync(outPath, `${JSON.stringify(sidebars, null, 2)}\n`, 'utf8');
console.log('  all references resolve');
console.log(`  wrote ${path.relative(ARCHIVE_DIR, outPath)} (${fs.statSync(outPath).size} bytes)`);
